mapper.select:
SELECT

FROM sys_flow_business

    tenant_id = #{tenantId}

        AND title LIKE CONCAT('%', #{processName}, '%')


        AND apply_user_name LIKE CONCAT('%', #{initiator}, '%')


        AND status = #{status}


        AND process_def_key = #{modelKey}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC, id DESC

SELECT DATE(stat_time) AS stat_date,
       SUM(created_count) AS created_count,
       SUM(completed_count) AS completed_count
FROM (
    SELECT create_time AS stat_time, 1 AS created_count, 0 AS completed_count
    FROM sys_flow_business
    WHERE tenant_id = #{tenantId}
      AND create_time >= #{startTime}
      AND create_time < #{endTime}
    UNION ALL
    SELECT end_time AS stat_time, 0 AS created_count, 1 AS completed_count
    FROM sys_flow_business
    WHERE tenant_id = #{tenantId}
      AND end_time >= #{startTime}
      AND end_time < #{endTime}
) daily_stat
GROUP BY DATE(stat_time)
ORDER BY stat_date ASC

